import type { ComponentProps } from 'react';

import { cn } from '@/lib/utils';

// As mesmas peças do table do shadcn, com o visual do Admin One: linhas listradas e bordas entre as
// colunas no desktop, e cada linha vira um cartão no celular, com o rótulo da coluna antes do valor.

function Table({ className, ...props }: ComponentProps<'table'>) {
  return (
    <div data-slot="table-container" className="relative w-full overflow-x-auto">
      <table data-slot="table" className={cn('w-full caption-bottom', className)} {...props} />
    </div>
  );
}

function TableHeader({ className, ...props }: ComponentProps<'thead'>) {
  return (
    <thead
      data-slot="table-header"
      className={cn('hidden lg:table-header-group', className)}
      {...props}
    />
  );
}

function TableBody({ className, ...props }: ComponentProps<'tbody'>) {
  return (
    <tbody
      data-slot="table-body"
      className={cn(
        'lg:[&>tr:hover]:bg-muted lg:[&>tr:nth-child(odd)]:bg-muted/50 dark:lg:[&>tr:nth-child(odd)]:bg-background/50',
        className,
      )}
      {...props}
    />
  );
}

function TableFooter({ className, ...props }: ComponentProps<'tfoot'>) {
  return (
    <tfoot data-slot="table-footer" className={cn('border-t font-medium', className)} {...props} />
  );
}

function TableRow({ className, ...props }: ComponentProps<'tr'>) {
  return (
    <tr
      data-slot="table-row"
      className={cn(
        'relative block max-w-full border-b-4 border-border transition-colors last:border-b-0 has-[[data-slot=checkbox][data-checked]]:bg-brand-muted! lg:table-row lg:border-b-0',
        className,
      )}
      {...props}
    />
  );
}

function TableHead({ className, ...props }: ComponentProps<'th'>) {
  return (
    <th
      data-slot="table-head"
      className={cn('p-3 text-left align-middle font-semibold whitespace-nowrap', className)}
      {...props}
    />
  );
}

interface TableCellProps extends ComponentProps<'td'> {
  // O nome da coluna, que aparece antes do valor no celular, onde o cabeçalho some.
  label?: string;
}

function TableCell({ className, label, ...props }: TableCellProps) {
  return (
    <td
      data-slot="table-cell"
      data-label={label}
      className={cn(
        'flex items-center justify-between gap-4 border-b border-border px-4 py-3 text-right align-top last:border-b-0 lg:table-cell lg:border-b-0 lg:p-3 lg:text-left lg:align-middle lg:not-first:border-l',
        'before:pr-3 before:text-left before:font-semibold before:content-[attr(data-label)] lg:before:hidden',
        className,
      )}
      {...props}
    />
  );
}

function TableCaption({ className, ...props }: ComponentProps<'caption'>) {
  return (
    <caption
      data-slot="table-caption"
      className={cn('mt-4 text-sm text-muted-foreground', className)}
      {...props}
    />
  );
}

export { Table, TableBody, TableCaption, TableCell, TableFooter, TableHead, TableHeader, TableRow };

'use client';

import { createContext, useContext, useState, type ReactNode } from 'react';

import { Checkbox } from '@/registry/frontend-ui/checkbox/ui/checkbox';

interface TableSelectionState {
  rowIds: readonly string[];
  selectedIds: ReadonlySet<string>;
  setSelectedIds: (selectedIds: ReadonlySet<string>) => void;
}

const TableSelectionContext = createContext<TableSelectionState | null>(null);

function useTableSelectionState(): TableSelectionState {
  const state = useContext(TableSelectionContext);
  if (state === null) {
    throw new Error('A seleção da tabela precisa estar dentro do TableSelection.');
  }
  return state;
}

interface TableSelectionProps {
  // Os ids das linhas da página. O que foi marcado e saiu da página deixa de contar.
  rowIds: readonly string[];
  children: ReactNode;
}

export function TableSelection({ rowIds, children }: TableSelectionProps) {
  const [selectedIds, setSelectedIds] = useState<ReadonlySet<string>>(() => new Set());

  return (
    <TableSelectionContext value={{ rowIds, selectedIds, setSelectedIds }}>
      {children}
    </TableSelectionContext>
  );
}

// As linhas marcadas, para a ação em lote (excluir, exportar).
export function useTableSelection() {
  const { rowIds, selectedIds, setSelectedIds } = useTableSelectionState();

  return {
    selectedIds: rowIds.filter((id) => selectedIds.has(id)),
    clearSelection: () => {
      setSelectedIds(new Set());
    },
  };
}

export function TableSelectAllCheckbox() {
  const { rowIds, selectedIds, setSelectedIds } = useTableSelectionState();
  const selectedCount = rowIds.filter((id) => selectedIds.has(id)).length;
  const isAllSelected = rowIds.length > 0 && selectedCount === rowIds.length;

  return (
    <Checkbox
      aria-label="Selecionar todas as linhas"
      checked={isAllSelected}
      indeterminate={selectedCount > 0 && !isAllSelected}
      onCheckedChange={(checked) => {
        if (checked) {
          setSelectedIds(new Set(rowIds));
          return;
        }
        setSelectedIds(new Set());
      }}
    />
  );
}

interface TableSelectRowCheckboxProps {
  rowId: string;
  // O que identifica a linha para o leitor de tela, como o nome do paciente.
  label: string;
}

export function TableSelectRowCheckbox({ rowId, label }: TableSelectRowCheckboxProps) {
  const { selectedIds, setSelectedIds } = useTableSelectionState();

  return (
    <Checkbox
      aria-label={`Selecionar ${label}`}
      checked={selectedIds.has(rowId)}
      onCheckedChange={(checked) => {
        const nextSelectedIds = new Set(selectedIds);
        if (checked) {
          nextSelectedIds.add(rowId);
        } else {
          nextSelectedIds.delete(rowId);
        }
        setSelectedIds(nextSelectedIds);
      }}
    />
  );
}

import { Fragment, type ReactElement, type ReactNode } from 'react';

import { buttonVariants } from '@/registry/frontend-ui/button/ui/button';
import { cn } from '@/lib/utils';

export interface PageLinkProps {
  className: string;
  children: ReactNode;
  'aria-current': 'page' | false;
  'aria-label': string;
}

interface TablePaginationProps {
  // Começa em 1.
  page: number;
  pageCount: number;
  hrefForPage: (page: number) => string;
  // O link do framework com o href e as props, como (href, props) => <Link href={href} {...props} />.
  // O padrão é um <a>.
  renderLink?: (href: string, props: PageLinkProps) => ReactElement;
}

function renderAnchor(href: string, props: PageLinkProps): ReactElement {
  return <a href={href} {...props} />;
}

const PAGE_LINK_CLASS = cn(
  buttonVariants({ variant: 'ghost', size: 'icon-sm' }),
  'bg-card aria-[current=page]:bg-accent aria-[current=page]:font-bold',
);

export function TablePagination({
  page,
  pageCount,
  hrefForPage,
  renderLink = renderAnchor,
}: TablePaginationProps) {
  const pages = Array.from({ length: pageCount }, (_, index) => index + 1);

  return (
    <nav
      aria-label="Paginação"
      className="flex flex-wrap items-center justify-between gap-3 border-t px-3 py-3 lg:px-6"
    >
      <div className="flex flex-wrap gap-2">
        {pages.map((pageNumber) => (
          <Fragment key={pageNumber}>
            {renderLink(hrefForPage(pageNumber), {
              className: PAGE_LINK_CLASS,
              children: pageNumber,
              'aria-current': pageNumber === page && 'page',
              'aria-label': `Página ${String(pageNumber)}`,
            })}
          </Fragment>
        ))}
      </div>
      <small>
        Página {page} de {pageCount}
      </small>
    </nav>
  );
}
